set -eu
APP_PW=$(openssl rand -base64 36 | tr -d '\n')
AUD_PW=$(openssl rand -base64 36 | tr -d '\n')
export APP_PW AUD_PW
install -d -m 700 /root/branch_stock_credentials
printf '%s:5432:branch_stock:stock_app:%s\n' "$NODE_IP" "$APP_PW" > /root/branch_stock_credentials/stock_app.pgpass
printf '%s:5432:branch_stock:auditor:%s\n' "$NODE_IP" "$AUD_PW" > /root/branch_stock_credentials/auditor.pgpass
chmod 600 /root/branch_stock_credentials/*.pgpass
cat > /tmp/branch_stock_roles.sql <<'ANTRIEB_SQL'
\set ON_ERROR_STOP on
\getenv app_pw APP_PW
\getenv aud_pw AUD_PW
CREATE ROLE stock_app LOGIN PASSWORD :[REDACTED] NOSUPERUSER NOCREATEDB NOCREATEROLE;
CREATE ROLE auditor LOGIN PASSWORD :[REDACTED] NOSUPERUSER NOCREATEDB NOCREATEROLE;
CREATE DATABASE branch_stock;
ANTRIEB_SQL
sudo -u postgres --preserve-env=APP_PW,AUD_PW psql -f /tmp/branch_stock_roles.sql
sudo -u postgres psql -v ON_ERROR_STOP=1 -d branch_stock -f /srv/legacy2/database-reader-writer-roles/stock.sql
cat > /tmp/branch_stock_grants.sql <<'ANTRIEB_SQL'
\set ON_ERROR_STOP on
REVOKE ALL ON DATABASE branch_stock FROM PUBLIC;
GRANT CONNECT ON DATABASE branch_stock TO stock_app, auditor;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
GRANT USAGE ON SCHEMA public TO stock_app, auditor;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
GRANT SELECT ON TABLE stock TO stock_app;
GRANT UPDATE (quantity) ON TABLE stock TO stock_app;
GRANT SELECT ON TABLE stock, supplier_costs TO auditor;
REVOKE ALL ON TABLE supplier_costs FROM stock_app;
ANTRIEB_SQL
sudo -u postgres psql -d branch_stock -f /tmp/branch_stock_grants.sql
sudo -u postgres psql -v ON_ERROR_STOP=1 -c "ALTER SYSTEM SET listen_addresses = '$NODE_IP';"
printf '\n# branch_stock remote roles from node2 only\nhost branch_stock stock_app 10.100.53.11/32 scram-sha-256\nhost branch_stock auditor 10.100.53.11/32 scram-sha-256\n' >> /etc/postgresql/16/main/pg_hba.conf
systemctl restart postgresql
rm -f /tmp/branch_stock_roles.sql /tmp/branch_stock_grants.sql
BLOB=$(tar -C /root/branch_stock_credentials -czf - stock_app.pgpass auditor.pgpass | openssl enc -aes-256-cbc -salt -pbkdf2 -pass env:CLUSTER_SSH_PRIVKEY | base64 -w0)
printf 'database-configured\ncredential-bundle=%s\n' "$BLOB"

